    /** Evaluates [predicate] with the domain's single implementation [predicates]. */
    @Suppress("CyclomaticComplexMethod")
    fun holds(
        predicate: EncounterPredicate,
        predicates: EncounterPredicates,
        facts: EncounterFacts,
    ): Boolean =
        when (predicate) {
            EncounterPredicate.PATIENT_IDENTITY_CONFIRMED -> predicates.patientIdentityConfirmed(facts)
            EncounterPredicate.SWAP_PARTNER_IDENTITY_CONFIRMED -> predicates.swapPartnerIdentityConfirmed(facts)
            EncounterPredicate.TRIAGE_RECORD_COMPLETE -> predicates.triageRecordComplete(facts)
            EncounterPredicate.ON_SITE_CELL_CONNECTED -> predicates.onSiteCellConnected(facts)
            EncounterPredicate.TARGET_BED_ASSIGNED_TO_ENCOUNTER -> predicates.targetBedAssignedToEncounter(facts)
            EncounterPredicate.TARGET_BED_FREE_FOR_NEW_PERIOD -> predicates.targetBedFreeForNewPeriod(facts)
            EncounterPredicate.BED_SWAP_PAIR_VALID -> predicates.bedSwapPairValid(facts)
            EncounterPredicate.SWAPPED_BEDS_ADMIT_BOTH_PATIENTS -> predicates.swappedBedsAdmitBothPatients(facts)
            EncounterPredicate.OVERRIDE_REASON_CHOSEN -> predicates.overrideReasonChosen(facts)
            EncounterPredicate.EFFECTIVE_TIME_AFTER_LOCATION_START -> predicates.effectiveTimeAfterLocationStart(facts)
            EncounterPredicate.DISPOSITION_CHOSEN -> predicates.dispositionChosen(facts)
            EncounterPredicate.RETURN_BED_AVAILABLE -> predicates.returnBedAvailable(facts)
            EncounterPredicate.DISCHARGED_FROM_BED -> predicates.dischargedFromBed(facts)
            EncounterPredicate.DISCHARGED_FROM_LEAVE -> predicates.dischargedFromLeave(facts)
            EncounterPredicate.DISCHARGED_BEFORE_ADMISSION -> predicates.dischargedBeforeAdmission(facts)
            EncounterPredicate.TRIAGE_RECORDED -> predicates.triageRecorded(facts)
            EncounterPredicate.NO_TRIAGE_RECORDED -> predicates.noTriageRecorded(facts)
            EncounterPredicate.PREVIOUS_BED_AVAILABLE -> predicates.previousBedAvailable(facts)
            EncounterPredicate.CORRECTED_TIMES_CONSISTENT -> predicates.correctedTimesConsistent(facts)
            EncounterPredicate.BACK_ENTRY_PERIODS_WELL_FORMED -> predicates.backEntryPeriodsWellFormed(facts)
            EncounterPredicate.BACK_ENTRY_PERIODS_FREE -> predicates.backEntryPeriodsFree(facts)
            EncounterPredicate.BACK_ENTRY_PERIODS_CONFLICT -> predicates.backEntryPeriodsConflict(facts)
            EncounterPredicate.ERROR_REASON_CHOSEN -> predicates.errorReasonChosen(facts)
            EncounterPredicate.WRONG_PATIENT_ERROR -> predicates.wrongPatientError(facts)
            EncounterPredicate.NOT_WRONG_PATIENT_ERROR -> predicates.notWrongPatientError(facts)
            EncounterPredicate.REPLACEMENT_ENCOUNTER_READY -> predicates.replacementEncounterReady(facts)
            EncounterPredicate.HAND_OVER_PERIOD_VALID -> predicates.handOverPeriodValid(facts)
            EncounterPredicate.CODING_AND_CHARGING_COMPLETE -> predicates.codingAndChargingComplete(facts)
            EncounterPredicate.REASON_ENTERED -> predicates.reasonEntered(facts)
            EncounterPredicate.PRIVILEGED_AND_AUDITED -> predicates.privilegedAndAudited(facts)
        }

    /** Applies [command] in [state] with [facts]; never changes state unless exactly one guard holds. */
    fun fire(
        state: EncounterState,
        command: EncounterCommand,
        predicates: EncounterPredicates,
        facts: EncounterFacts,
    ): Outcome<EncounterState, EncounterCommand, EncounterPredicate, EncounterEffect> =
        spec.fire(state, command) { holds(it, predicates, facts) }
}
